    public static void main(String[] args) throws IOException {
        if (INPUTS.length != TOTAL || OUTPUTS.length != TOTAL) throw new IllegalStateException("Expected 101 cases");
        Path baseDir = Paths.get("Testcases");
        if (!Files.isDirectory(baseDir)) baseDir = Paths.get("../Testcases");
        Path inputDir = baseDir.resolve("input"), outputDir = baseDir.resolve("output");
        Files.createDirectories(inputDir); Files.createDirectories(outputDir);
        for (int i = 0; i < TOTAL; i++) {
            String suffix = String.format("%02d", i + 1);
            Files.writeString(inputDir.resolve("input" + suffix + ".txt"), INPUTS[i] + System.lineSeparator());
            Files.writeString(outputDir.resolve("output" + suffix + ".txt"), OUTPUTS[i] + System.lineSeparator());
        }
        System.out.println("Generated " + TOTAL + " test cases successfully.");
        System.out.println("Input directory: " + inputDir.toAbsolutePath());
        System.out.println("Output directory: " + outputDir.toAbsolutePath());
    }
